/* Zella: "التوصيل المتوقع" box under the product page's own buy buttons (above wa-help.js's WhatsApp line).
   Range: next delivery day -> 3 delivery days after today (Cairo time); the courier delivers every day except Friday.
   Official holidays are not counted. */
(function () {
  if (window.__zellaEta) return; window.__zellaEta = 1;
  var DAYS = ['الأحد', 'الاتنين', 'التلات', 'الأربع', 'الخميس', 'الجمعة', 'السبت'];
  var MON = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  var css = '#zeta{display:flex;align-items:center;gap:8px;margin:12px 0 4px;padding:10px 12px;border:1px solid #e2e8f0;border-radius:12px;background:#fff;font-size:15px;color:#334155;direction:rtl}' +
    '#zeta svg{flex:0 0 auto;color:#0f766e}#zeta b{font-weight:800;color:#0f172a}#zeta span{color:#0f766e;font-weight:700}';

  function cairoNow() { var p = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()).split('-'); return new Date(+p[0], +p[1] - 1, +p[2]); }
  function addWork(d, n) { var x = new Date(d); while (n > 0) { x.setDate(x.getDate() + 1); if (x.getDay() !== 5) n--; } return x; }   // Friday off
  function fmt(d) { return DAYS[d.getDay()] + ' ' + d.getDate(); }
  // owner, 2026-11-25: range = next delivery day (tomorrow, or Saturday after a Thursday) up to 3 delivery days
  // after today (always 72 h or more); the courier delivers every day except Friday.
  var TRUCK = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" d="M2 6h11v9H2zM13 9h4l3 3v3h-7z"/><circle cx="6" cy="17" r="1.8" fill="#fff" stroke="currentColor" stroke-width="1.8"/><circle cx="16.5" cy="17" r="1.8" fill="#fff" stroke="currentColor" stroke-width="1.8"/></svg>';
  function etaText() {
    var t = cairoNow(), a = addWork(t, 1), b = addWork(t, 3);
    var range = a.getMonth() === b.getMonth() ? fmt(a) + ' – ' + fmt(b) + ' ' + MON[b.getMonth()] : fmt(a) + ' ' + MON[a.getMonth()] + ' – ' + fmt(b) + ' ' + MON[b.getMonth()];
    return TRUCK + '<b>التوصيل المتوقع:</b><span>' + range + '</span>';
  }
  function isProduct() { return /^\/products\/[^\/]+/.test(location.pathname); }
  function addCss() { if (!document.getElementById('zbe-css')) { var s = document.createElement('style'); s.id = 'zbe-css'; s.textContent = css; document.head.appendChild(s); } }
  function run() {
    var oe = document.getElementById('zeta');
    if (!isProduct()) { if (oe) oe.remove(); return; }
    var key = location.pathname;
    // 1) delivery line after the page's own buy buttons (the block holding "اضغط هنا للشراء")
    if (!oe || oe.dataset.k !== key || !document.body.contains(oe)) {
      var buy = [].filter.call(document.querySelectorAll('button'), function (b) { return /اضغط هنا للشراء/.test(b.textContent); })[0];
      if (buy && buy.parentElement) {
        addCss(); if (oe) oe.remove();
        var e = document.createElement('div'); e.id = 'zeta'; e.dataset.k = key; e.innerHTML = etaText();
        buy.parentElement.insertAdjacentElement('afterend', e);
      }
    }
  }
  setInterval(run, 500); run();
})();

